package com.amit.headroom;
import android.appwidget.AppWidgetManager;import android.content.ComponentName;import com.getcapacitor.JSObject;import com.getcapacitor.Plugin;import com.getcapacitor.PluginCall;import com.getcapacitor.annotation.CapacitorPlugin;
@CapacitorPlugin(name="HeadRoomWidget") public class HeadRoomWidgetPlugin extends Plugin{@com.getcapacitor.PluginMethod public void syncTasks(PluginCall call){String tasks=call.getString("tasks","[]");getContext().getSharedPreferences("HeadRoomWidget",android.content.Context.MODE_PRIVATE).edit().putString("tasks",tasks).apply();AppWidgetManager m=AppWidgetManager.getInstance(getContext());ComponentName n=new ComponentName(getContext(),HeadRoomWidget.class);m.notifyAppWidgetViewDataChanged(m.getAppWidgetIds(n),R.id.widgetList);call.resolve(new JSObject());}}